// Pet Shop Brawl: buy weird pets, merge three into one, watch them brawl. data.js and sim.js hold the rules; run.js the money;
// shop.js and battle.js the feel. Bot opponents live in ghosts.js, generated by tools/gen-ghosts.mjs.
import { createGame } from "./pogo.js";
import { paintPets, paintUI, sheet } from "./art.js";
import { SONGS } from "./audio.js";
import { battleScene } from "./battle.js";
import { loadMeta } from "./meta.js";
import { BACKGROUND, menus, startRun } from "./menus.js";
import { G } from "./ui.js";
import { shopScene } from "./shop.js";

const browser = typeof location !== "undefined", q = browser ? new URLSearchParams(location.search) : null;
const seed = q?.get("seed") ? Number(q.get("seed")) : browser ? (Date.now() ^ (performance.now() * 1000)) >>> 0 : 1;
const game = createGame({
    view: { width: 360, height: 640, landscape: { width: 640, height: 360 } },
    background: BACKGROUND, seed, maxDpr: 2.5,
    actions: { confirm: ["Enter", "Space", "pad:a"], roll: ["KeyR"], buy1: ["Digit1"], buy2: ["Digit2"], buy3: ["Digit3"], buy4: ["Digit4"], buy5: ["Digit5"] },
});
G.game = game; G.meta = loadMeta(game);
game.audio.muted = !G.meta.sound; game.haptics.enabled = G.meta.haptics;
G.playSong = (name) => { G.song = name; if (G.meta.music && G.playing !== name) { G.playing = name; game.music(SONGS[name]); } if (!G.meta.music) { game.stopMusic(); G.playing = null; } };
paintUI(game);
const painting = paintPets(game);
if (painting) game.assets.wait(painting.then(() => document.getElementById("load")?.remove()));
else if (browser) document.getElementById("load")?.remove();
menus(game); shopScene(game); battleScene(game);
game.startRun = (o) => startRun(game, o);
game.pb = G; G.sheetFull = () => sheet.full;
game.start("title");
export { game };
